    for target in record.get("source_refs", [])[:32]:
        add("source_refs", target)
    for identity in record.get("related_quest_ids", [])[:32]:
        add("related_quest", f"quest:{identity}")
    reverse = []
    if kind == "conversation":
        reverse = [
