        baseline, options, formatting = _review_request_shape(connection, run, gateway, packet)
        request = ModelRequest(provider_id=run["provider_id"], model_id=run["model_id"], messages=baseline, max_output_tokens=min(8192, run["output_limit"], run["model_max_output_tokens"]), max_retries=0, **options)
        base = _review_input_reservation(gateway, request, formatting)
        results = []
